import os
import selectors
import signal
import subprocess
import time


def run_bounded(argv, timeout, max_bytes):
    if not isinstance(argv, list) or not argv or not all(isinstance(x, str) for x in argv):
        raise ValueError('argv must be a nonempty string list')
    if isinstance(timeout, bool) or not isinstance(timeout, (int, float)) or not .01 <= timeout <= 30:
        raise ValueError('invalid timeout')
    if isinstance(max_bytes, bool) or not isinstance(max_bytes, int) or not 1 <= max_bytes <= 1048576:
        raise ValueError('invalid capture bound')
    deadline = time.monotonic() + timeout
    process = subprocess.Popen(argv, stdin=subprocess.DEVNULL, stdout=subprocess.PIPE,
                               stderr=subprocess.PIPE, start_new_session=True, bufsize=0)
    selector = selectors.DefaultSelector()
    captured = {'stdout': bytearray(), 'stderr': bytearray()}
    totals = {'stdout': 0, 'stderr': 0}
    reaped = False

    def exited():
        # Keep the group leader's PID reserved until group cleanup is finished.
        return os.waitid(os.P_PID, process.pid, os.WEXITED | os.WNOHANG | os.WNOWAIT) is not None

    def signal_group(number):
        try:
            os.killpg(process.pid, number)
        except ProcessLookupError:
            pass

    def drain(wait):
        for entry, _ in selector.select(wait):
            try:
                chunk = os.read(entry.fd, 65536)
            except BlockingIOError:
                continue
            if not chunk:
                selector.unregister(entry.fileobj)
                entry.fileobj.close()
                continue
            name = entry.data
            totals[name] += len(chunk)
            remaining = max_bytes - len(captured[name])
            if remaining > 0:
                captured[name].extend(chunk[:remaining])

    try:
        for name in captured:
            stream = getattr(process, name)
            os.set_blocking(stream.fileno(), False)
            selector.register(stream, selectors.EVENT_READ, name)
        timed_out = False
        while not (exited() and not selector.get_map()):
            remaining = deadline - time.monotonic()
            if remaining <= 0:
                timed_out = True
                break
            drain(min(.01, remaining))
        if timed_out:
            signal_group(signal.SIGTERM)
            grace = time.monotonic() + .10
            while time.monotonic() < grace and not (exited() and not selector.get_map()):
                drain(min(.01, max(0, grace - time.monotonic())))
        # This also stops an in-group descendant that closed its inherited pipes.
        signal_group(signal.SIGKILL)
        finish = time.monotonic() + .25
        while selector.get_map() and time.monotonic() < finish:
            drain(min(.01, max(0, finish - time.monotonic())))
        process.wait(timeout=1)
        reaped = True
        return {'returncode': process.returncode,
                'stdout': bytes(captured['stdout']).decode('utf-8', 'replace'),
                'stderr': bytes(captured['stderr']).decode('utf-8', 'replace'),
                'stdout_total': totals['stdout'], 'stderr_total': totals['stderr'],
                'truncated': any(totals[name] > max_bytes for name in totals),
                'timed_out': timed_out}
    finally:
        if not reaped:
            signal_group(signal.SIGKILL)
            process.wait(timeout=1)
        for entry in list(selector.get_map().values()):
            selector.unregister(entry.fileobj)
            entry.fileobj.close()
        selector.close()
        for stream in (process.stdout, process.stderr):
            if not stream.closed:
                stream.close()
